import{_ as p,a0 as r,w as o,s as d,ao as l,I as n,x as s,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"用 fastjar 和 gjar 構建一個 JAR 文件 | LCTT x X-CMD","titleTemplate":false,"description":"用 fastjar 和 gjar 構建一個 JAR 文件 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 fastjar 和 gjar 構建一個 JAR 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 fastjar 和 gjar 構建一個 JAR 文件 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210818 Build a JAR file with fastjar and gjar","title":"用 fastjar 和 gjar 構建一個 JAR 文件","tag":"202108","desc":""},"relativePath":"202108/20210818 Build a JAR file with fastjar and gjar.md","filePath":"[post].md"}'),h={name:"202108/20210818 Build a JAR file with fastjar and gjar.md"};function g(u,a,f,k,c,b){const i=r("Link");return o(),d("div",null,[a[24]||(a[24]=l(`<h1 id="用-fastjar-和-gjar-構建一個-jar-文件" tabindex="-1">用 fastjar 和 gjar 構建一個 JAR 文件 <a class="header-anchor" href="#用-fastjar-和-gjar-構建一個-jar-文件" aria-label="Permalink to “用 fastjar 和 gjar 構建一個 JAR 文件”">​</a></h1><blockquote><p>fastjar、gjar 和 jar 等工具可以幫助你手動或以編程方式構建 JAR 文件，而其他工具鏈，如 Maven 和 Gradle 提供了依賴性管理的功能。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/27/105207oj4f44t4vbkkv4iq.jpg" alt=""></p><p>根據我的經驗，Java 的許多優點之一是它能夠以整齊方便的包（稱為 JAR，或 Java 歸檔）來提供應用程序。JAR 文件使用户很容易下載並啓動他們想嘗試的應用，很容易將該應用從一台計算機轉移到另一台計算機（而且 Java 是跨平台的，所以可以鼓勵自由分享），而且對於新的程序員來説，查看 JAR 文件的內容，以找出使 Java 應用運行的原因是很容易理解的。</p><p>創建 JAR 文件的方法有很多，包括 Maven 和 Gradle 等工具鏈解決方案，以及 IDE 中的一鍵構建功能。然而，也有一些獨立的命令，如 <code>jarfast</code>、<code>gjar</code> 和普通的 <code>jar</code>，它們對於快速和簡單的構建是很有用的，並且可以演示 JAR 文件運行所需要的東西。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>在 Linux 上，你可能已經有了 <code>fastjar</code>、<code>gjar</code> 或作為 OpenJDK 包或 GCJ（GCC-Java）的一部分的 <code>jar</code> 命令。你可以通過輸入不帶參數的命令來測試這些命令是否已經安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fastjar</span></span>
<span class="line"><span>Try &#39;fastjar --help&#39; for more information.</span></span>
<span class="line"><span>$ gjar</span></span>
<span class="line"><span>jar: must specify one of -t, -c, -u, -x, or -i</span></span>
<span class="line"><span>jar: Try &#39;jar --help&#39; for more information</span></span>
<span class="line"><span>$ jar</span></span>
<span class="line"><span>Usage: jar [OPTION...] [ [--release VERSION] [-C dir] files] ...</span></span>
<span class="line"><span>Try \`jar --help&#39; for more information.</span></span></code></pre></div><p>我安裝了所有這些命令，但你只需要一個。所有這些命令都能夠構建一個 JAR。</p><p>在 Fedora 等現代 Linux 系統上，輸入一個缺失的命令你的操作系統提示安裝它。</p>`,10)),n("p",null,[a[2]||(a[2]=s("另外，你可以直接從 ",-1)),e(i,{href:"https://adoptopenjdk.net/"},{default:t(()=>[...a[0]||(a[0]=[s("AdoptOpenJDK.net",-1)])]),_:1}),a[3]||(a[3]=s(" 為 Linux、MacOS 和 Windows ",-1)),e(i,{href:"https://opensource.com/article/19/11/install-java-linux"},{default:t(()=>[...a[1]||(a[1]=[s("安裝 Java",-1)])]),_:1}),a[4]||(a[4]=s("。",-1))]),a[25]||(a[25]=l(`<h3 id="構建-jar" tabindex="-1">構建 JAR <a class="header-anchor" href="#構建-jar" aria-label="Permalink to “構建 JAR”">​</a></h3><p>首先，你需要構建一個 Java 應用。</p><p>為了簡單起見，在一個名為 <code>hello.java</code> 的文件中創建一個基本的 “hello world” 應用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class Main {</span></span>
<span class="line"><span>public static void main(String[] args) {</span></span>
<span class="line"><span>    System.out.println(&quot;Hello Java World&quot;);</span></span>
<span class="line"><span>}}</span></span></code></pre></div><p>這是一個簡單的應用，在某種程度上淡化了管理外部依賴關係在現實世界中的重要性。不過，這也足以讓你開始瞭解創建 JAR 所需的基本概念了。</p><p>接下來，創建一個清單文件。清單文件描述了 JAR 的 Java 環境。在這個例子裏，最重要的信息是識別主類，這樣執行 JAR 的 Java 運行時就知道在哪裏可以找到應用的入口點。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mdir META-INF</span></span>
<span class="line"><span>$ echo &quot;Main-Class: Main&quot; &gt; META-INF/MANIFEST.MF</span></span></code></pre></div><h3 id="編譯-java-字節碼" tabindex="-1">編譯 Java 字節碼 <a class="header-anchor" href="#編譯-java-字節碼" aria-label="Permalink to “編譯 Java 字節碼”">​</a></h3><p>接下來，把你的 Java 文件編譯成 Java 字節碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ javac hello.java</span></span></code></pre></div><p>另外，你也可以使用 GCC 的 Java 組件來編譯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcj -C hello.java</span></span></code></pre></div><p>無論哪種方式，都會產生文件 <code>Main.class</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file Main.class</span></span>
<span class="line"><span>Main.class: compiled Java class data, version XX.Y</span></span></code></pre></div><h3 id="創建-jar" tabindex="-1">創建 JAR <a class="header-anchor" href="#創建-jar" aria-label="Permalink to “創建 JAR”">​</a></h3><p>你有了所有需要的組件，這樣你就可以創建 JAR 文件了。</p><p>我經常包含 Java 源碼給好奇的用户參考，這隻需 <code>META-INF</code> 目錄和類文件即可。</p>`,17)),n("p",null,[a[6]||(a[6]=n("code",null,"fastjar",-1)),a[7]||(a[7]=s(" 命令使用類似於 ",-1)),e(i,{href:"https://opensource.com/article/17/7/how-unzip-targz-file"},{default:t(()=>[...a[5]||(a[5]=[s("tar 命令",-1)])]),_:1}),a[8]||(a[8]=s("的語法。",-1))]),a[26]||(a[26]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fastjar cvf hello.jar META-INF Main.class</span></span></code></pre></div><p>另外，你也可以用 <code>gjar</code>，方法大致相同，只是 <code>gjar</code> 需要你明確指定清單文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gjar cvf world.jar Main.class -m META-INF/MANIFEST.MF</span></span></code></pre></div><p>或者你可以使用 <code>jar</code> 命令。注意這個命令不需要清單文件，因為它會自動為你生成一個，但為了安全起見，我明確定義了主類：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ jar --create --file hello.jar --main-class=Main Main.class</span></span></code></pre></div><p>測試你的應用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -jar hello.jar</span></span>
<span class="line"><span>Hello Java World</span></span></code></pre></div><h3 id="輕鬆打包" tabindex="-1">輕鬆打包 <a class="header-anchor" href="#輕鬆打包" aria-label="Permalink to “輕鬆打包”">​</a></h3><p>像 <code>fastjar</code>、<code>gjar</code> 和 <code>jar</code> 這樣的工具可以幫助你手動或以編程方式構建 JAR 文件，而其他工具鏈如 Maven 和 Gradle 則提供了依賴性管理的功能。一個好的 IDE 可能會集成這些功能中的一個或多個。</p><p>無論你使用什麼解決方案，Java 都為分發你的應用代碼提供了一個簡單而統一的目標。</p><hr>`,11)),n("p",null,[a[10]||(a[10]=s("via: ",-1)),e(i,{href:"https://opensource.com/article/21/8/fastjar"},{default:t(()=>[...a[9]||(a[9]=[s("https://opensource.com/article/21/8/fastjar",-1)])]),_:1})]),n("p",null,[a[15]||(a[15]=s("作者：",-1)),e(i,{href:"https://opensource.com/users/seth"},{default:t(()=>[...a[11]||(a[11]=[s("Seth Kenlon",-1)])]),_:1}),a[16]||(a[16]=s(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[12]||(a[12]=[s("lujun9972",-1)])]),_:1}),a[17]||(a[17]=s(" 譯者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:t(()=>[...a[13]||(a[13]=[s("geekpi",-1)])]),_:1}),a[18]||(a[18]=s(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...a[14]||(a[14]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[21]||(a[21]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[19]||(a[19]=[s("LCTT",-1)])]),_:1}),a[22]||(a[22]=s(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...a[20]||(a[20]=[s("Linux中國",-1)])]),_:1}),a[23]||(a[23]=s(" 榮譽推出",-1))])])}const J=p(h,[["render",g]]);export{v as __pageData,J as default};
